demos = json.load(open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-2/play/users/u047/system/state/workspace/demos.json'))
input_data = demos['demo_grids']['input']
output_data = demos['demo_grids']['output']
bg = 6

# Find all non-background positions in output, grouped into adjacent pairs
# A "pattern" is two adjacent cells that aren't background

output_patterns = []
non_bg_rows = []

for r in range(16):
    non_bg_cols_in_row = []
    for c, val in enumerate(output_data[r]):
        if val != bg:
            non_bg_cols_in_row.append(c)
    if non_bg_cols_in_row:
        non_bg_rows.append(r)
        # Find pairs of adjacent non-background cells
        for i in range(len(non_bg_cols_in_row) - 1):
            if non_bg_cols_in_row[i+1] == non_bg_cols_in_row[i] + 1:
                pattern = (val == non_bg_cols_in_row[i], val == non_bg_cols_in_row[i+1])
                p_val = output_data[r][non_bg_cols_in_row[i]]
                p_val2 = output_data[r][non_bg_cols_in_row[i+1]]
                output_patterns.append((r, non_bg_cols_in_row[i]+non_bg_cols_in_row[i+1], p_val, p_val2))
    else:
        output_patterns.append((r, -1, -1, -1))

print(f"Found {len([x for x in output_patterns if x[2] != -1])} output patterns (non-background pairs)")

# Now mark input 1s positions
input_1s = []
for r in range(16):
    for c, val in enumerate(input_data[r]):
        if val == 1:
            input_1s.append((r, c))

print(f"\nInput 1s: {len(input_1s)}")

# For each input 1, find the output pattern
print("\nMapping input 1s to output patterns:")
for r, c in input_1s:
    # Look for a pattern in row r or nearby rows
    for op_row, op_col1, op_v1, op_v2 in output_patterns:
        if op_col1 != -1 and op_col1 >= c and op_col1 <= c + 1:
            print(f"  Input 1 at ({r},{c}) → Output pattern at ({op_row},{op_col1}) with values ({op_v1},{op_v2})")

